exercises.solution:
def column_total(table, name):
    if name not in table[0]:
        return 0
    position = table[0].index(name)
    total = 0
    for row in table[1:]:
        value = row[position]
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            total += value
    return total

